const D = { energy: .55, scale: 1, density: .55, speed: 1, melt: .4, haze: .5, hue: 200, x: .4, y: .82, style: 'blueice', act: 'frozen', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 200;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];

const STY = {
  // cold blue-white ice on an overcast day, teal englacial cores
  blueice:  { rockT:[210,18,30], rockB:[206,14,20], ice:[196,10,88], iceC:[198,54,60], iceD:[204,40,34],
              glint:[190,6,99], pool:[204,42,16], snow:[198,6,96], sky:[204,16,64], grain:16, rocky:1 },
  // low sun raking: warm amber highlights, cold blue shade
  goldlit:  { rockT:[26,30,30], rockB:[24,28,18], ice:[40,22,84], iceC:[200,50,56], iceD:[210,44,30],
              glint:[44,40,99], pool:[212,44,16], snow:[44,20,96], sky:[36,34,60], grain:18, rocky:1 },
  // moonlit nocturne: deep blue, faint inner glow
  nocturne: { rockT:[228,40,12], rockB:[224,36,8], ice:[210,26,52], iceC:[214,62,48], iceD:[220,50,26],
              glint:[204,20,90], pool:[224,48,8], snow:[206,16,74], sky:[230,44,16], grain:12, rocky:1 },
  // ABSTRACTED x-ray: translucent internal structure, cyan-white, no rock
  xray:     { rockT:[240,30,8], rockB:[240,26,6], ice:[188,30,84], iceC:[186,60,70], iceD:[190,44,48],
              glint:[184,10,99], pool:[240,26,10], snow:[186,20,92], sky:[240,24,10], grain:4, rocky:0 },
  // ABSTRACTED sumi ink: the cascade as tonal dry-brush strokes
  ink:      { rockT:[30,8,26], rockB:[30,6,16], ice:[30,4,84], iceC:[30,8,56], iceD:[30,10,36],
              glint:[30,2,96], pool:[30,6,18], snow:[30,3,90], sky:[30,4,74], grain:28, rocky:1 }
};
const st = STY[P.style] || STY.blueice;

const en = Math.max(0, Math.min(1, P.energy));
const hz = Math.max(0, Math.min(1, P.haze));
const poolY = height * P.y;
const fallW = u * (.34 + P.density * .28) * P.scale;   // width of the frozen cascade
const cx0 = width * P.x;                                // centre of the falls
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.ice.remove(); S.drift.remove(); }
  S.sky = mk(W, H); S.ice = mk(W, H); S.drift = mk(W, H);

  // rock walls + narrow sky slot behind the falls
  const g = S.sky; g.noStroke();
  const skyC = sh(st.sky), rT = sh(st.rockT), rB = sh(st.rockB);
  for (let yy = 0; yy < H; yy++) { const c = L3(skyC, L3(rT, rB, yy / H), Math.min(1, yy / (H * .5))); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }
  if (st.rocky) {
    // flanking cliff walls, hazed, with rough hatched texture
    for (let side = -1; side <= 1; side += 2) {
      const inner = cx0 + side * fallW * .55;
      g.noStroke();
      const wallC = L3(rT, skyC, hz * .3);
      g.fill(wallC[0], wallC[1], wallC[2], 100);
      g.beginShape();
      const outer = side < 0 ? -u * .05 : W + u * .05;
      g.vertex(outer, -10); g.vertex(outer, H + 10);
      for (let yy = H + 10; yy >= -10; yy -= u * .04) {
        const jag = inner + side * Math.sin(yy * .01 + fr(side + 3) * 6.3) * u * .04 + side * Math.sin(yy * .03) * u * .02;
        g.vertex(jag, yy);
      }
      g.endShape(g.CLOSE);
      // hatch on the rock
      g.strokeWeight(Math.max(.5, u * .0012));
      for (let h = 0; h < 40; h++) {
        const hy = fr(h * 3 + side * 50 + 1) * H;
        const hx = side < 0 ? fr(h * 3 + 2) * inner : inner + fr(h * 3 + 2) * (W - inner);
        g.stroke(rB[0], rB[1], Math.max(2, rB[2] + (fr(h) - .5) * 12), 26);
        g.line(hx, hy, hx + u * .02, hy + u * .012);
      }
      g.noStroke();
    }
  }

  // the frozen cascade: bundles of vertical ice columns / icicle flutes with translucent cores
  const q = S.ice; q.noStroke();
  const iceC = sh(st.ice), iceCore = sh(st.iceC), iceD = sh(st.iceD);
  const topY = poolY - u * (.55 + P.density * .1) * P.scale;
  const nCol = Math.floor(10 + P.density * 22);
  for (let i = 0; i < nCol; i++) {
    const f = i / nCol;
    const colx = cx0 - fallW / 2 + f * fallW + (fr(i * 3 + 11) - .5) * fallW / nCol;
    const cw = fallW / nCol * (.7 + fr(i * 3 + 12) * .9);
    const botY = poolY - u * .01 + (fr(i * 3 + 13) - .3) * u * .04;    // icicle tips near the pool
    const depth = (Math.abs(f - .5) < .3) ? 1 : .8;                    // core columns brighter
    // ice mass
    q.fill(iceC[0], iceC[1], Math.min(99, iceC[2] * depth), 90);
    q.beginShape();
    q.vertex(colx - cw / 2, topY);
    q.vertex(colx + cw / 2, topY);
    q.vertex(colx + cw * .32, botY);            // taper to an icicle
    q.vertex(colx, botY + u * (.01 + fr(i) * .03));
    q.vertex(colx - cw * .32, botY);
    q.endShape(q.CLOSE);
    // translucent englacial core
    q.fill(iceCore[0], iceCore[1], iceCore[2], 46);
    q.rect(colx - cw * .16, topY, cw * .32, botY - topY);
    // flute shadows on both sides
    q.strokeWeight(Math.max(.6, cw * .1));
    q.stroke(iceD[0], iceD[1], iceD[2], 50);
    q.line(colx - cw * .42, topY + u * .02, colx - cw * .3, botY);
    q.line(colx + cw * .42, topY + u * .02, colx + cw * .3, botY);
    q.noStroke();
    // lit edge
    const litSide = P.x < .5 ? -1 : 1;
    q.fill(sh(st.glint)[0], st.glint[1], st.glint[2], 34 * (.4 + en));
    q.rect(colx + litSide * cw * .3, topY, cw * .1, botY - topY);
  }
  // a horizontal ice lip / bulge partway down
  q.fill(iceC[0], iceC[1] * .8, Math.min(99, iceC[2]), 70);
  q.ellipse(cx0, topY + (poolY - topY) * .42, fallW * 1.05, u * .05 * P.scale);
  S.iceTop = topY;

  // spindrift / ice-fog band (tileable)
  const dC = L3(sh(st.snow), sh(st.sky), .3);
  S.drift.noStroke();
  for (let i = 0; i < 12; i++) {
    const bx = fr(i * 5 + 71) * W, by = fr(i * 5 + 72) * H;
    const bw = u * (.4 + fr(i * 5 + 73) * .8), bhh = u * (.04 + fr(i * 5 + 74) * .1);
    for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 3; kk++) {
      S.drift.fill(dC[0], dC[1] * (1 - kk * .1), Math.min(99, dC[2] + kk * 3), 7 * (1 - kk * .2));
      S.drift.ellipse(bx + rep * W, by + kk * bhh * .1, bw * (1 - kk * .1), bhh * (1 - kk * .08));
    }
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 6) + 6) % 6;
const ACT = { frozen: { melt: .5, drift: 1 }, thaw: { melt: 1 + sec * .18, drift: 1 }, spindrift: { melt: .5, drift: 1.8 } };
const act = ACT[P.act] || ACT.frozen;
const melt = Math.max(0, Math.min(1.8, P.melt * act.melt));

noStroke();
image(S.sky, 0, 0);

// spindrift behind the ice
const DW = S.drift.width;
const dx1 = ((-K.t * u * .01 * P.speed * act.drift % DW) + DW) % DW;
push(); tint(0, 0, 100, 60 * act.drift); image(S.drift, dx1 - DW, -u * .1); image(S.drift, dx1, -u * .1); pop();

// the frozen cascade
image(S.ice, 0, 0);

// ---------------- specular glints travelling down the columns (motion floor + internal shimmer) ----------------
const glintC = sh(st.glint);
blendMode(ADD);
const topY = S.iceTop;
const ng = Math.floor(16 + P.density * 24);
for (let i = 0; i < ng; i++) {
  const gx = cx0 - fallW / 2 + fr(i * 3 + 101) * fallW;
  const life = ((K.t * (.06 + fr(i * 3 + 102) * .1) * P.speed + fr(i * 3 + 103)) % 1);
  const gy = topY + life * (poolY - topY);
  const tw = Math.sin(K.t * (1 + fr(i) * 2) + i) * .5 + .5;
  fill(glintC[0], glintC[1] * .5, glintC[2], (10 + 26 * tw * en));
  ellipse(gx, gy, u * .006 * (.5 + tw), u * .02 * (.5 + tw));
}
blendMode(BLEND);

// ---------------- the live meltwater trickle behind/through the ice ----------------
if (melt > .05) {
  const trickC = sh(st.iceC);
  strokeWeight(Math.max(1, u * .003 * melt)); noFill();
  for (let s = 0; s < Math.floor(1 + melt * 3); s++) {
    const tx = cx0 + (fr(s + 201) - .5) * fallW * .5;
    stroke(trickC[0], trickC[1] * .7, Math.min(99, trickC[2] + 20), 30 + 30 * melt);
    beginShape();
    for (let yy = topY; yy <= poolY; yy += u * .02)
      vertex(tx + Math.sin(yy * .06 + K.t * 3 + s) * u * .006 + Math.sin(yy * .02 - K.t * 1.3) * u * .01, yy);
    endShape();
  }
  // drips falling into the pool
  const nd = Math.floor(melt * 8);
  for (let i = 0; i < nd; i++) {
    const dxp = cx0 + (fr(i * 3 + 211) - .5) * fallW;
    const life = ((K.t * (.5 + fr(i * 3 + 212)) * P.speed + fr(i * 3 + 213)) % 1);
    const dyp = topY + (poolY - topY) * (.5 + life * .5);
    fill(trickC[0], trickC[1] * .5, Math.min(99, trickC[2] + 24), 60 * (1 - life));
    ellipse(dxp, dyp, u * .004, u * .012);
  }
}

// ---------------- the plunge pool: dark, with a broken reflection of the ice ----------------
const poolC = sh(st.pool);
fill(poolC[0], poolC[1], poolC[2]); rect(0, poolY, width, height - poolY);
push();
const rH = height - poolY;
for (let i = 0; i < Math.floor(10 + P.density * 8); i++) {
  const f = i / 16;
  const yy = poolY + f * rH;
  const ph = K.t * (.5 + f * .8) * P.speed;
  strokeWeight(Math.max(.6, u * .002)); noFill();
  stroke(sh(st.ice)[0], st.ice[1] * .5, Math.min(99, poolC[2] + 20 + 30 * f), (18 + 26 * f) * (.4 + en));
  beginShape();
  for (let x = cx0 - fallW; x <= cx0 + fallW; x += u * .02)
    vertex(x + Math.sin(x * .04 + ph) * u * .01 * (.3 + f), yy);
  endShape();
}
pop(); noStroke();

// drifting snow / frost in front
const snowC = sh(st.snow);
const nsn = Math.floor(24 + P.density * 40);
for (let i = 0; i < nsn; i++) {
  const life = ((K.t * (.03 + fr(i * 3 + 301) * .05) * P.speed + fr(i * 3 + 302)) % 1);
  const sx = (fr(i * 3 + 303) * width + Math.sin(K.t * (.3 + fr(i) * .4) + i) * u * .04 + width) % width;
  const sy = life * height;
  fill(snowC[0], snowC[1] * .4, snowC[2], 20 + 30 * fr(i * 3 + 304));
  ellipse(sx, sy, u * .0022 * (.5 + fr(i)), u * .0022 * (.5 + fr(i)));
}

// grain, vignette, alpha
if (st.grain > 6) {
  const ng2 = Math.floor(st.grain * 5);
  for (let i = 0; i < ng2; i++) {
    const gx = ((fr(i * 3 + 401) * width) + Math.sin(K.t * .01 + i) * u * .002 + width) % width;
    const gy = fr(i * 3 + 402) * height;
    fill(st.pool[0], st.pool[1] * .4, fr(i * 3 + 403) > .5 ? 92 : 8, 3 + fr(i) * 5);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .05);
  stroke(sh(st.pool)[0], st.pool[1], 6, 18 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();
if (P.alpha < 1) { fill(sh(st.pool)[0], st.pool[1] * .5, 6, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
